package br.com.pelotavision;
import static org.junit.Assert.*;
import org.junit.*;import org.junit.runner.RunWith;import org.robolectric.*;import org.robolectric.annotation.*;
import android.graphics.*;import android.view.*;import java.util.*;import java.io.*;import java.nio.file.*;import org.json.*;
@RunWith(RobolectricTestRunner.class) @Config(sdk=33,manifest=Config.NONE,qualifiers="w400dp-h820dp-xhdpi") @GraphicsMode(GraphicsMode.Mode.NATIVE)
public class BeltDemoTest {
 static void png(Bitmap b,File file)throws Exception{try(FileOutputStream out=new FileOutputStream(file)){assertTrue(b.compress(Bitmap.CompressFormat.PNG,100,out));}}
 @Test public void suppliedPhotoRendersActualEditorAndRoiReportWithoutInventingPhysicalWidth()throws Exception{
  File dir=new File(System.getProperty("pelotavision.validationDir"),"belt-0.9.0");JSONObject input=new JSONObject(new String(Files.readAllBytes(new File(dir,"analysis.json").toPath()),java.nio.charset.StandardCharsets.UTF_8));Bitmap photo=BitmapFactory.decodeFile(new File(dir,"input_correia.jpg").toString());assertNotNull(photo);List<PelletDetector.Detection> objects=new ArrayList<>();List<CrackAnalysis.Entry> entries=new ArrayList<>();JSONArray ds=input.getJSONArray("objects");
  for(int i=0;i<ds.length();i++){JSONObject d=ds.getJSONObject(i);PelletDetector.Detection seed=new PelletDetector.Detection(d.getDouble("crack_x"),d.getDouble("crack_y"),d.getDouble("crack_radius"),Math.PI*Math.pow(d.getDouble("crack_radius"),2),d.getDouble("roundness"),d.getBoolean("partial"),d.getBoolean("crack_review"));objects.add(new PelletDetector.Detection(seed,d.getDouble("x"),d.getDouble("y"),d.getDouble("a"),d.getDouble("b"),d.getDouble("angle"),d.getBoolean("fitted"),d.isNull("support")?Double.NaN:d.getDouble("support"),d.isNull("rms")?Double.NaN:d.getDouble("rms"),d.getBoolean("partial"),d.getBoolean("review")));JSONArray rs=d.getJSONArray("crack_runs");float[] runs=new float[rs.length()];for(int j=0;j<runs.length;j++)runs[j]=(float)rs.getDouble(j);entries.add(new CrackAnalysis.Entry(i+1,CrackAnalysis.Status.valueOf(d.getString("crack_status")),runs,d.isNull("crack_score")?Double.NaN:d.getDouble("crack_score"),"random_forest_20261018_v1"));}
  PelletDetector.Result all=new PelletDetector.Result(objects,photo.getWidth(),photo.getHeight(),objects.size(),0,false,input.getString("method"));CrackAnalysis cracks=new CrackAnalysis(all.width,all.height,50,0,entries);InterestRegion roi=new InterestRegion(InterestRegion.Shape.RECTANGLE,440,340,860,940);List<Integer> ids=roi.indices(all);assertFalse(ids.isEmpty());PelletDetector.Result selected=InterestRegion.select(all,ids);
  Bitmap report=PhotoComposer.compose(photo,selected,cracks.select(ids),null,roi,objects.size()-ids.size(),true);png(report,new File(dir,"Exemplo_ROI_sem_largura_fisica.png"));report.recycle();
  try(org.robolectric.android.controller.ActivityController<MainActivity> ctl=Robolectric.buildActivity(MainActivity.class).setup()){
   MainActivity a=ctl.get();ObjectCalibrationTest.setup(a);Bitmap dummy=(Bitmap)ObjectCalibrationTest.get(a,"photoBitmap");ObjectCalibrationTest.set(a,"photoBitmap",photo);dummy.recycle();ObjectCalibrationTest.set(a,"photoAllResult",all);ObjectCalibrationTest.set(a,"photoAllCracks",cracks);ObjectCalibrationTest.set(a,"originalWidth",photo.getWidth());ObjectCalibrationTest.set(a,"originalHeight",photo.getHeight());ObjectCalibrationTest.call(a,"applyRegion",new Class[]{InterestRegion.class},roi);
   ObjectCalibrationTest.call(a,"showBeltCalibration",new Class[]{});android.app.Dialog dialog=org.robolectric.shadows.ShadowDialog.getLatestDialog();View root=dialog.getWindow().getDecorView();BeltEditorView editor=root.findViewWithTag("belt_editor");editor.edges(new BeltCalibration.Edges(new double[]{211,245,211,1288,1098,245,1098,1288},true));
   root.measure(View.MeasureSpec.makeMeasureSpec(800,View.MeasureSpec.EXACTLY),View.MeasureSpec.makeMeasureSpec(1640,View.MeasureSpec.EXACTLY));root.layout(0,0,800,1640);Bitmap screen=Bitmap.createBitmap(800,1640,Bitmap.Config.ARGB_8888);root.draw(new Canvas(screen));png(screen,new File(dir,"Tela_Calibracao_Correia.png"));screen.recycle();dialog.dismiss();
   ObjectCalibrationTest.call(a,"showRoiZoom",new Class[]{InterestRegion.class},roi);dialog=org.robolectric.shadows.ShadowDialog.getLatestDialog();root=dialog.getWindow().getDecorView();root.measure(View.MeasureSpec.makeMeasureSpec(800,View.MeasureSpec.EXACTLY),View.MeasureSpec.makeMeasureSpec(1640,View.MeasureSpec.EXACTLY));root.layout(0,0,800,1640);screen=Bitmap.createBitmap(800,1640,Bitmap.Config.ARGB_8888);root.draw(new Canvas(screen));png(screen,new File(dir,"Tela_Zoom_ROI.png"));screen.recycle();dialog.dismiss();
  }
 }
}
